/**
 * Set the path currently being compiled.
 *
 * @param  string  $path
 * @return void
 */
public function setPath($path)
{
    $this->path = $path;
}

/**
 * Compile the given Blade template contents.
 *
 * @param  string  $value
 * @return string
 */
public function compileString($value)
{
    [$this->footer, $result] = [[], ''];

    foreach ($this->prepareStringsForCompilationUsing as $callback) {
        $value = $callback($value);
    }

    $value = $this->storeUncompiledBlocks($value);

    // First we will compile the Blade component tags. This is a precompile style
    // step which compiles the component Blade tags into @component directives
    // that may be used by Blade. Then we should call any other precompilers.
    $value = $this->compileComponentTags(
        $this->compileComments($value)
    );

    foreach ($this->precompilers as $precompiler) {
        $value = $precompiler($value);
    }

    // Here we will loop through all of the tokens returned by the Zend lexer and
    // parse each one into the corresponding valid PHP. We will then have this
    // template as the correctly rendered PHP that can be rendered natively.
    foreach (token_get_all($value) as $token) {
        $result .= is_array($token) ? $this->parseToken($token) : $token;
    }

    if (! empty($this->rawBlocks)) {
        $result = $this->restoreRawContent($result);
    }

    // If there are any footer lines that need to get added to a template we will
    // add them here at the end of the template. This gets used mainly for the
    // template inheritance via the extends keyword that should be appended.
    if (count($this->footer) > 0) {
        $result = $this->addFooters($result);
    }

    if (! empty($this->echoHandlers)) {
        $result = $this->addBladeCompilerVariable($result);
    }

    return str_replace(
        ['##BEGIN-COMPONENT-CLASS##', '##END-COMPONENT-CLASS##'],
        '',
        $result);
}

/**
 * Evaluate and render a Blade string to HTML.
 *
 * @param  string  $string
 * @param  array  $data

/**
 * Replace the raw placeholders with the original code stored in the raw blocks.
 *
 * @param  string  $result
 * @return string
 */
protected function restoreRawContent($result)
{
    $result = preg_replace_callback('/'.$this->getRawPlaceholder('(\d+)').'/', function ($matches) {
        return $this->rawBlocks[$matches[1]];
    }, $result);

    $this->rawBlocks = [];

    return $result;
}

/**
 * Get a placeholder to temporarily mark the position of raw blocks.
 *
 * @param  int|string  $replace
 * @return string
 */
protected function getRawPlaceholder($replace)
{
    return str_replace('#', $replace, '@__raw_block_#__@');
}

/**
 * Add the stored footers onto the given content.
 *
 * @param  string  $result
 * @return string
 */
protected function addFooters($result)
{
    return ltrim($result, "\n")
            ."\n".implode("\n", array_reverse($this->footer));
}

